using System;
using System.Reflection;
using System.Linq;

var dllPath = args.Length > 0 ? args[0] : "";
if (string.IsNullOrEmpty(dllPath)) {
    Console.WriteLine("Usage: dotnet run <dll-path>");
    return;
}

try {
    var assembly = Assembly.LoadFrom(dllPath);
    var publicTypes = assembly.GetTypes()
        .Where(t => t.IsPublic && !t.Name.StartsWith("<"))
        .OrderBy(t => t.FullName)
        .ToList();

    Console.WriteLine($"Found {publicTypes.Count} public types in {Path.GetFileName(dllPath)}\n");

    foreach (var type in publicTypes) {
        Console.WriteLine($"\n{'='*80}");
        Console.WriteLine($"Type: {type.FullName}");
        if (type.BaseType != null && type.BaseType != typeof(object)) {
            Console.WriteLine($"Base: {type.BaseType.FullName}");
        }

        var interfaces = type.GetInterfaces().Where(i => i.IsPublic).ToList();
        if (interfaces.Any()) {
            Console.WriteLine($"Interfaces: {string.Join(", ", interfaces.Select(i => i.FullName))}");
        }

        // Properties
        var props = type.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static)
            .OrderBy(p => p.Name)
            .ToList();
        if (props.Any()) {
            Console.WriteLine("\nPublic Properties:");
            foreach (var prop in props) {
                var access = "";
                if (prop.CanGet && prop.CanSet) access = "get; set;";
                else if (prop.CanGet) access = "get;";
                else if (prop.CanSet) access = "set;";
                var typeName = prop.PropertyType.IsGenericType 
                    ? prop.PropertyType.Name.Split('`')[0] + "<" + string.Join(", ", prop.PropertyType.GetGenericArguments().Select(a => a.Name)) + ">"
                    : prop.PropertyType.Name;
                Console.WriteLine($"  {typeName} {prop.Name} {{ {access} }}");
            }
        }

        // Methods (excluding special methods like get_/set_)
        var methods = type.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static | BindingFlags.DeclaredOnly)
            .Where(m => !m.IsSpecialName)
            .OrderBy(m => m.Name)
            .ToList();
        if (methods.Any()) {
            Console.WriteLine("\nPublic Methods:");
            foreach (var method in methods.GroupBy(m => m.Name)) {
                foreach (var m in method) {
                    var parameters = string.Join(", ", m.GetParameters().Select(p => {
                        var pType = p.ParameterType.IsGenericType
                            ? p.ParameterType.Name.Split('`')[0] + "<...>"
                            : p.ParameterType.Name;
                        return $"{pType} {p.Name}";
                    }));
                    var returnType = m.ReturnType.IsGenericType
                        ? m.ReturnType.Name.Split('`')[0] + "<...>"
                        : m.ReturnType.Name;
                    Console.WriteLine($"  {returnType} {m.Name}({parameters})");
                }
            }
        }

        // Constructors
        var constructors = type.GetConstructors(BindingFlags.Public).ToList();
        if (constructors.Any()) {
            Console.WriteLine("\nPublic Constructors:");
            foreach (var ctor in constructors) {
                var parameters = string.Join(", ", ctor.GetParameters().Select(p => {
                    var pType = p.ParameterType.IsGenericType
                        ? p.ParameterType.Name.Split('`')[0] + "<...>"
                        : p.ParameterType.Name;
                    return $"{pType} {p.Name}";
                }));
                Console.WriteLine($"  {type.Name}({parameters})");
            }
        }
    }
} catch (Exception ex) {
    Console.WriteLine($"Error: {ex.Message}");
}
