using System.ComponentModel;
using System.Net;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration -----------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string ModelId = "gpt-4o-mini-2024-07-18";

// --- Tools -------------------------------------------------------------------

var notebook = new Notebook();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(SearchWeb,
        name: "search_web",
        description: "Search the web for a query and return a list of result snippets."),
    AIFunctionFactory.Create(notebook.SaveNote,
        name: "save_note",
        description: "Save a research note with a title and body for later reference."),
    AIFunctionFactory.Create(notebook.ReadNotes,
        name: "read_notes",
        description: "Read all previously saved research notes."),
};

// --- Agent setup -------------------------------------------------------------

IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(ModelId)
    .AsIChatClient();

var agent = new ChatClientAgent(
    chatClient,
    new ChatClientAgentOptions
    {
        Name = "ResearchAgent",
        Description = "An AI agent that researches topics by searching the web and taking notes.",
        Instructions = """
            You are a research assistant. When given a topic:
            1. Use search_web to find relevant information (make 2-3 searches with varied queries).
            2. Use save_note to record key findings as you go.
            3. Use read_notes to review everything you collected.
            4. Provide a well-structured summary of your research to the user.
            Be thorough but concise. Cite the sources (URLs) you found.
            """,
        Tools = tools,
        ChatOptions = new ChatOptions
        {
            Temperature = 0.2f,
            MaxOutputTokens = 2048,
        },
    });

// --- Main loop ---------------------------------------------------------------

Console.WriteLine("Research Agent ready. Type a topic to research (or 'quit' to exit).\n");

while (true)
{
    Console.Write("> ");
    var topic = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    Console.WriteLine($"\nResearching: {topic}\n");

    var session = await agent.CreateSessionAsync();
    var runOptions = new ChatClientAgentRunOptions
    {
        MaximumIterations = 10,
    };

    try
    {
        var response = await agent.RunAsync(topic, session, runOptions);

        foreach (var message in response.Messages)
        {
            if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
            {
                Console.WriteLine(message.Text);
            }
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Error: {ex.Message}");
    }

    Console.WriteLine();
}

// --- Tool implementations ----------------------------------------------------

[Description("Search the web for a query and return a list of result snippets.")]
static async Task<IList<SearchResult>> SearchWeb(
    [Description("The search query string")] string query)
{
    var encoded = WebUtility.UrlEncode(query);
    var url = $"https://html.duckduckgo.com/html/?q={encoded}";

    using var http = new HttpClient();
    http.DefaultRequestHeaders.UserAgent.ParseAdd(
        "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

    try
    {
        var html = await http.GetStringAsync(url);
        return ParseDuckDuckGoResults(html);
    }
    catch (Exception ex)
    {
        return [new SearchResult("Search failed", ex.Message, "")];
    }
}

static List<SearchResult> ParseDuckDuckGoResults(string html)
{
    var results = new List<SearchResult>();
    const string snippetMarker = "result__snippet";
    const string titleMarker = "result__a";
    const string urlMarker = "result__url";

    var pos = 0;
    while (results.Count < 5 && pos < html.Length)
    {
        // Find snippet
        var snippetIdx = html.IndexOf(snippetMarker, pos, StringComparison.Ordinal);
        if (snippetIdx < 0) break;

        var title = ExtractTagContent(html, titleMarker, Math.Max(0, snippetIdx - 2000), snippetIdx + 500);
        var snippet = ExtractTagContent(html, snippetMarker, snippetIdx, snippetIdx + 2000);
        var link = ExtractHref(html, urlMarker, Math.Max(0, snippetIdx - 2000), snippetIdx + 500);

        if (!string.IsNullOrWhiteSpace(snippet))
        {
            results.Add(new SearchResult(
                StripHtml(title),
                StripHtml(snippet),
                link.Trim()));
        }

        pos = snippetIdx + snippetMarker.Length;
    }

    if (results.Count == 0)
        results.Add(new SearchResult("No results", "No results found for this query.", ""));

    return results;
}

static string ExtractTagContent(string html, string className, int searchStart, int searchEnd)
{
    searchEnd = Math.Min(searchEnd, html.Length);
    var classIdx = html.IndexOf(className, searchStart, StringComparison.Ordinal);
    if (classIdx < 0 || classIdx >= searchEnd) return "";

    var gtIdx = html.IndexOf('>', classIdx);
    if (gtIdx < 0) return "";

    var closeIdx = html.IndexOf('<', gtIdx + 1);
    if (closeIdx < 0) return html[(gtIdx + 1)..];

    return html[(gtIdx + 1)..closeIdx];
}

static string ExtractHref(string html, string className, int searchStart, int searchEnd)
{
    searchEnd = Math.Min(searchEnd, html.Length);
    var classIdx = html.IndexOf(className, searchStart, StringComparison.Ordinal);
    if (classIdx < 0 || classIdx >= searchEnd) return "";

    var hrefIdx = html.LastIndexOf("href=\"", classIdx, Math.Min(classIdx - searchStart, 500),
        StringComparison.Ordinal);
    if (hrefIdx < 0)
    {
        hrefIdx = html.IndexOf("href=\"", classIdx, StringComparison.Ordinal);
        if (hrefIdx < 0 || hrefIdx >= searchEnd) return "";
    }

    var start = hrefIdx + 6;
    var end = html.IndexOf('"', start);
    if (end < 0) return "";

    return html[start..end];
}

static string StripHtml(string text) =>
    System.Text.RegularExpressions.Regex.Replace(
        WebUtility.HtmlDecode(text), "<[^>]+>", "").Trim();

// --- Models ------------------------------------------------------------------

record SearchResult(string Title, string Snippet, string Url);

class Notebook
{
    private readonly List<Note> _notes = [];

    [Description("Save a research note with a title and body.")]
    public string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("Body content of the note")] string body)
    {
        _notes.Add(new Note(title, body));
        return $"Note saved: '{title}' ({_notes.Count} total notes)";
    }

    [Description("Read all previously saved research notes.")]
    public IList<Note> ReadNotes() => _notes.AsReadOnly();
}

record Note(string Title, string Body);

