     http.DefaultRequestHeaders.UserAgent.ParseAdd(
         "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

     try
     {
         var html = await http.GetStringAsync(url);
         return ParseDuckDuckGoResults(html);
     }
     catch (Exception ex)
     {
         return [new SearchResult("Search failed", ex.Message, "")];
     }
 }

 static List<SearchResult> ParseDuckDuckGoResults(string html)
 {
     var results = new List<SearchResult>();
     const string snippetMarker = "result__snippet";
     const string titleMarker = "result__a";
     const string urlMarker = "result__url";

     var pos = 0;
     while (results.Count < 5 && pos < html.Length)
     {
         // Find snippet
         var snippetIdx = html.IndexOf(snippetMarker, pos, StringComparison.Ordinal);
         if (snippetIdx < 0) break;

         var title = ExtractTagContent(html, titleMarker, Math.Max(0, snippetIdx - 2000), snippetIdx + 500);
         var snippet = ExtractTagContent(html, snippetMarker, snippetIdx, snippetIdx + 2000);
         var link = ExtractHref(html, urlMarker, Math.Max(0, snippetIdx - 2000), snippetIdx + 500);

         if (!string.IsNullOrWhiteSpace(snippet))
         {
             results.Add(new SearchResult(
                 StripHtml(title),
                 StripHtml(snippet),
                 link.Trim()));
         }

         pos = snippetIdx + snippetMarker.Length;
     }

     if (results.Count == 0)
         results.Add(new SearchResult("No results", "No results found for this query.", ""));

     return results;
 }

 static string ExtractTagContent(string html, string className, int searchStart, int searchEnd)
 {
     searchEnd = Math.Min(searchEnd, html.Length);
     var classIdx = html.IndexOf(className, searchStart, StringComparison.Ordinal);
     if (classIdx < 0 || classIdx >= searchEnd) return "";

     var gtIdx = html.IndexOf('>', classIdx);
     if (gtIdx < 0) return "";

     var closeIdx = html.IndexOf('<', gtIdx + 1);
     if (closeIdx < 0) return html[(gtIdx + 1)..];

     return html[(gtIdx + 1)..closeIdx];
 }

 static string ExtractHref(string html, string className, int searchStart, int searchEnd)
 {
     searchEnd = Math.Min(searchEnd, html.Length);
     var classIdx = html.IndexOf(className, searchStart, StringComparison.Ordinal);
     if (classIdx < 0 || classIdx >= searchEnd) return "";

     var hrefIdx = html.LastIndexOf("href=\"", classIdx, Math.Min(classIdx - searchStart, 500),
